def find_2x2_blocks(arr, rows=0, cols=0):
    """Find all 2x2 blocks with uniform color"""
    blocks = []
    for r in range(rows, arr.shape[0] - 1):
        for c in range(cols, arr.shape[1] - 1):
            top_left = arr[r, c]
            top_right = arr[r, c+1]
            bottom_left = arr[r+1, c]
            bottom_right = arr[r+1, c+1]
            if top_left == top_right == bottom_left == bottom_right:
                blocks.append((r, c, top_left))
    return blocks

